function validate([s, numOps]) {
  if (s.length < 1 || s.length > 100000) return 's needs 1 to 10^5 characters.';
  if (!/^[01]+$/.test(s)) return "s may contain only '0' and '1'.";
  if (numOps < 0 || numOps > s.length) return 'numOps is between 0 and the length of s.';
  return null;
}

