function minLength(s, numOps) {
  const n = s.length;
  // Lengths of the blocks of equal characters, left to right.
  const runs = [];
  let start = 0;
  for (let i = 1; i <= n; i++) {
    if (i === n || s[i] !== s[i - 1]) {
      runs.push(i - start);
      start = i;
    }
  }
  // A limit of 1 means s must alternate; count the flips that turn s into 0101...
  let mismatches = 0;
  for (let i = 0; i < n; i++) {
    if (Number(s[i]) !== i % 2) mismatches++;
  }
  if (Math.min(mismatches, n - mismatches) <= numOps) return 1;
  // For a limit of 2 or more, a block of length len needs floor(len / (limit + 1)) flips.
  let left = 2;
  let right = n;
  while (left < right) {
    const mid = Math.floor((left + right) / 2);
    let flips = 0;
    for (const length of runs) flips += Math.floor(length / (mid + 1));
    if (flips <= numOps) {
      right = mid;
    } else {
      left = mid + 1;
    }
  }
  return left;
}

