function minLength(s, numOps) {
  const n = s.length;
  // Try each limit in turn; a DP over every flip choice finds the fewest flips that keep all blocks within it.
  for (let limit = 1; limit <= n; limit++) {
    // cost[c][r]: fewest flips for the prefix so far when it ends in character c inside a block of length r.
    let cost = [new Array(limit + 1).fill(Infinity), new Array(limit + 1).fill(Infinity)];
    for (const c of [0, 1]) cost[c][1] = Number(s[0]) === c ? 0 : 1;
    for (let i = 1; i < n; i++) {
      const next = [new Array(limit + 1).fill(Infinity), new Array(limit + 1).fill(Infinity)];
      for (const c of [0, 1]) {
        for (let r = 1; r <= limit; r++) {
          if (cost[c][r] === Infinity) continue;
          for (const d of [0, 1]) {
            const flip = Number(s[i]) === d ? 0 : 1;
            const length = d === c ? r + 1 : 1;
            if (length <= limit) next[d][length] = Math.min(next[d][length], cost[c][r] + flip);
          }
        }
      }
      cost = next;
    }
    if (Math.min(...cost[0], ...cost[1]) <= numOps) return limit;
  }
  return n;
}

