function generate(rand, size) {
  const n = size === 'large' ? 10000 : 1 + Math.floor(rand() * 12);
  // Build s from blocks of random lengths, some of them long, so that flips matter.
  const longest = size === 'large' ? 2000 : 1 + Math.floor(rand() * n);
  let s = '';
  let bit = rand() < 0.5 ? '0' : '1';
  while (s.length < n) {
    s += bit.repeat(1 + Math.floor(rand() * longest));
    bit = bit === '0' ? '1' : '0';
  }
  s = s.slice(0, n);
  // Mostly few operations, so that the answer is neither n nor 1 too often.
  const numOps = size === 'large' ? (rand() < 0.25 ? Math.floor(rand() * (n + 1)) : Math.floor(rand() * 60)) : Math.floor(rand() * rand() * (n + 1));
  return [s, numOps];
}
